diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..664234d 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,11 +6,41 @@ export interface Record {
   warns: readonly string[];
 }

+const OPERATIONAL_OVERHEAD_VARIANTS = new Set([
+  "ops will not take on another stateful service",
+  "we cannot add infrastructure that someone has to operate",
+  "no new always-on components for v1",
+]);
+
+const isOperationalOverheadConstraint = (text: string): boolean =>
+  OPERATIONAL_OVERHEAD_VARIANTS.has(text);
+
+const deduplicateConstraints = (entries: readonly string[]): string[] => {
+  const seen = new Set<string>();
+  let operationalOverheadSeen = false;
+  const result: string[] = [];
+
+  for (const entry of entries) {
+    if (isOperationalOverheadConstraint(entry)) {
+      if (!operationalOverheadSeen) {
+        result.push("no new operational burden — ops will not take on stateful services or always-on infrastructure");
+        operationalOverheadSeen = true;
+      }
+    } else if (!seen.has(entry)) {
+      seen.add(entry);
+      result.push(entry);
+    }
+  }
+  return result;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
+    const deduplicatedLimits = deduplicateConstraints(record.limits);
+
     for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
+    for (const limit of deduplicatedLimits) lines.push(`- limit: ${limit}`);
     for (const warn of record.warns) lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
